 const m={price:{symbol,longName:name,quoteType:fund?'ETF':'EQUITY',currency:'USD',regularMarketTime:Date.parse('2026-10-23T20:00Z')/1000,marketCap:v(5e12),regularMarketOpen:v(212),regularMarketPreviousClose:v(212.21),regularMarketDayLow:v(210),regularMarketDayHigh:v(214),averageDailyVolume3Month:v(118e6)},summaryProfile:{sector:'Technology',industry:'Semiconductors',country:'United States',city:'Santa Clara',fullTimeEmployees:36000,longBusinessSummary:'A deterministic company profile for browser verification.',website:'https://example.com',irWebsite:'https://example.com/investors'},summaryDetail:{trailingPE:v(27.04),forwardPE:v(24),dividendYield:v(.0047),dividendRate:v(1),beta:v(2.22),fiftyTwoWeekLow:v(164.27),fiftyTwoWeekHigh:v(243.37),totalAssets:fund?v(450e9):undefined},defaultKeyStatistics:{trailingEps:v(7.91),mostRecentQuarter:{fmt:'2026-07-26'},floatShares:v(23.3e9),sharesOutstanding:v(24e9),shortPercentOfFloat:v(.01),dateShortInterest:{fmt:'2026-10-15'},netIncomeToCommon:v(192e9),annualReportExpenseRatio:fund?v(.002):undefined,fundFamily:fund?'Invesco':undefined,category:fund?'Large Growth':undefined},financialData:{financialCurrency:symbol==='TSM'?'TWD':'USD',totalRevenue:v(302e9),profitMargins:v(.63),totalCash:v(62e9),totalDebt:v(10e9),freeCashflow:v(0),debtToEquity:v(16.97)},calendarEvents:{earnings:{earningsDate:fund?[]:[{fmt:symbol==='TSLA'?'2026-10-21':'2026-11-17'}],isEarningsDateEstimate:true,earningsAverage:v(2.47),revenueAverage:v(108e9)},exDividendDate:{fmt:'2026-09-10'}},earnings:{defaultMethodology:'nongaap',financialsChart:{yearly:[{date:2026,revenue:v(215e9),earnings:v(120e9)}],quarterly:[{date:'2Q2026',fiscalQuarter:'2Q2027',revenue:v(60e9),earnings:v(35e9)}]},earningsChart:{quarterly:[{date:'2Q2026',fiscalQuarter:'2Q2027',actual:v(2.22),estimate:v(2.09),reportedDate:{fmt:'2026-08-26'}}]}}};
